import torch
import torch.nn as nn
import math
from torch.utils.cpp_extension import load_inline

fused_kernel_code = """
#include <torch/extension.h>
#include <cuda_runtime.h>

__global__ void fused_linear_swish_scale_kernel(
    const float* input, const float* weight, const float* bias,
    float* output, int B, int IN, int OUT, float scale) {

    int tid = blockIdx.x * blockDim.x + threadIdx.x;
    if(tid >= B * OUT) return;

    int row = tid / OUT;
    int col = tid % OUT;

    float sum = 0.0f;
    for(int i=0; i<IN; ++i) {
        sum += input[row*IN + i] * weight[col*IN + i];
    }
    sum += bias[col];

    float swish = sum * (1.0f / (1.0f + expf(-sum)));
    output[tid] = swish * scale;
}

torch::Tensor fused_op_cuda(
    torch::Tensor input, torch::Tensor weight, 
    torch::Tensor bias, float scaling_factor) {

    auto B = input.size(0);
    auto IN = input.size(1);
    auto OUT = weight.size(0);

    auto output = torch::empty({B, OUT}, input.options());

    int threads = 256;
    int blocks = (B * OUT + threads - 1) / threads;

    fused_linear_swish_scale_kernel<<<blocks, threads>>>(
        input.data_ptr<float>(),
        weight.data_ptr<float>(),
        bias.data_ptr<float>(),
        output.data_ptr<float>(),
        B, IN, OUT, scaling_factor
    );

    return output;
}
"""

cpp_interface = "torch::Tensor fused_op_cuda(torch::Tensor, torch::Tensor, torch::Tensor, float);"

fused_module = load_inline(
    name='fused_module',
    cpp_sources=cpp_interface,
    cuda_sources=fused_kernel_code,
    functions=['fused_op_cuda'],
    verbose=True
)

class ModelNew(nn.Module):
    def __init__(self, in_features, out_features, scaling_factor):
        super().__init__()
        self.in_features = in_features
        self.out_features = out_features
        self.scaling_factor = scaling_factor

        self.weight = nn.Parameter(torch.Tensor(out_features, in_features))
        self.bias = nn.Parameter(torch.Tensor(out_features))
        self.reset_parameters()

    def reset_parameters(self):
        nn.init.kaiming_uniform_(self.weight, a=math.sqrt(5))
        fan_in, _ = nn.init._calculate_fan_in_and_fan_out(self.weight)
        bound = 1 / math.sqrt(fan_in) if fan_in > 0 else 0
        nn.init.uniform_(self.bias, -bound, bound)

    def forward(self, x):
        return fused_module.fused_op_cuda(x, self.weight, self.bias, self.scaling_factor)
